1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type Result = { premium: number } | { payout: number; remainingCap: number };
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
28	const CURSE_SURCHARGE_RATE = 0.5;
29	const HIGH_ENCHANTMENT_THRESHOLD = 5;
30	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
31	const LOYALTY_YEARS_THRESHOLD = 2;
32	const LOYALTY_DISCOUNT_RATE = 0.2;
33	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
34	
35	/**
36	 * What the MHPCO charges to insure a type, before any modifier.
37	 *
38	 * Deliberately NOT the same table as `INSURANCE_VALUES`, and deliberately not
39	 * derived from it — see the note there.
40	 */
41	const BASE_PREMIUMS: Record<string, number> = {
42	  sword: 100,
43	  amulet: 60,
44	  staff: 80,
45	  potion: 40,
46	  rune: 25,
47	  moonstone: 25,
48	};
49	
50	/**
51	 * What the MHPCO considers a type to be WORTH. Only the payout cap reads this.
52	 *
53	 * Every value here is currently exactly 10 × the type's base premium, which
54	 * makes this table look like derivable duplication of `BASE_PREMIUMS`. It is
55	 * not: the two encode different facts that merely agree numerically today. The
56	 * ratio is a coincidence of the MHPCO's price list, not a rule of it.
57	 *
58	 * Collapsing them — `INSURANCE_VALUES[t]` to `BASE_PREMIUMS[t] * 10` — would
59	 * put every premium modifier on the path to the cap, since modifiers apply to
60	 * the base premium. "caps a cursed sword policy at 2000 G based on the
61	 * unmodified insurance value" is the executable guard: the cursed sword's
62	 * premium is modified to 165 G while its cap stays 2 × 1000 = 2000 G. A
63	 * derived table would let the 50 % curse surcharge inflate the cap to 3000 G,
64	 * paying the customer MORE for insuring a cursed item. The separation is what
65	 * keeps premium modifiers out of valuation.
66	 */
67	const INSURANCE_VALUES: Record<string, number> = {
68	  sword: 1000,
69	  amulet: 600,
70	  staff: 800,
71	  potion: 400,
72	  rune: 250,
73	  moonstone: 250,
74	};
75	
76	const DEDUCTIBLE_PER_DAMAGE = 100;
77	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
78	const HALF_REIMBURSEMENT_RATE = 0.5;
79	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
80	
81	const BLOCK_SIZE = 3;
82	const BLOCK_PREMIUM = 60;
83	
84	/** Items that share the same `type`, and so are priced together. */
85	type AlikeItems = Item[];
86	
87	const groupAlikeItems = (items: Item[]): AlikeItems[] => {
88	  const byType = new Map<string, AlikeItems>();
89	  items.forEach((item) => byType.set(item.type, [...(byType.get(item.type) ?? []), item]));
90	  return [...byType.values()];
91	};
92	
93	const formsBlock = (items: AlikeItems): boolean => items.length === BLOCK_SIZE;
94	
95	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
96	
97	const alikeItemsBasePremium = (alikeItems: AlikeItems): number =>
98	  formsBlock(alikeItems)
99	    ? BLOCK_PREMIUM
100	    : alikeItems.reduce((total, item) => total + itemBasePremium(item), 0);
101	
102	const totalBasePremium = (items: Item[]): number =>
103	  groupAlikeItems(items).reduce((total, alikeItems) => total + alikeItemsBasePremium(alikeItems), 0);
104	
105	const isCursed = (item: Item): boolean => item.cursed === true;
106	
107	const isHighlyEnchanted = (item: Item): boolean =>
108	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
109	
110	/**
111	 * An additive rate rule: contributes `rate` × some base premium, but only to
112	 * subjects the rule `applies` to. Every rule is an independent additive term —
113	 * nothing compounds onto a running total — so a discount is simply a negative
114	 * `rate` rather than a subtraction applied at some point in a sequence.
115	 */
116	type RateRule<Subject> = { applies: (subject: Subject) => boolean; rate: number };
117	
118	/**
119	 * The combined rate of every rule that applies to `subject`. Callers multiply
120	 * this by the relevant base premium once, which keeps each rule additive.
121	 */
122	const combinedRate = <Subject>(rules: RateRule<Subject>[], subject: Subject): number =>
123	  rules.filter(({ applies }) => applies(subject)).reduce((total, { rate }) => total + rate, 0);
124	
125	const ITEM_SURCHARGES: RateRule<Item>[] = [
126	  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
127	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
128	];
129	
130	const itemSurcharge = (item: Item): number =>
131	  itemBasePremium(item) * combinedRate(ITEM_SURCHARGES, item);
132	
133	/**
134	 * Summed across the policy's items, but each term is charged on the item's own
135	 * base premium — so this is item-scoped pricing that merely totals up, unlike
136	 * `policyAdjustments`, which rates the policy base as a whole.
137	 */
138	const itemSurchargesTotal = (items: Item[]): number =>
139	  items.reduce((total, item) => total + itemSurcharge(item), 0);
140	
141	/** Everything a policy-wide rule may look at when deciding whether it applies. */
142	type Policy = { customer: Customer; priorContracts: number };
143	
144	const isLoyalCustomer = ({ customer }: Policy): boolean =>
145	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
146	
147	const isFollowUpContract = ({ priorContracts }: Policy): boolean => priorContracts > 0;
148	
149	/**
150	 * Charged once per quote on the policy's base premium.
151	 *
152	 * The unconditional first-insurance surcharge is deliberately not in this table:
153	 * see `FIRST_INSURANCE_SURCHARGE_RATE` at the quote site.
154	 */
155	const POLICY_ADJUSTMENTS: RateRule<Policy>[] = [
156	  { applies: isLoyalCustomer, rate: -LOYALTY_DISCOUNT_RATE },
157	  { applies: isFollowUpContract, rate: -FOLLOW_UP_DISCOUNT_RATE },
158	];
159	
160	const policyAdjustments = (policyBasePremium: number, policy: Policy): number =>
161	  policyBasePremium * combinedRate(POLICY_ADJUSTMENTS, policy);
162	
163	const quotePremium = (items: Item[], policy: Policy): number => {
164	  const policyBasePremium = totalBasePremium(items);
165	  // The first-insurance surcharge has no condition to test: the MHPCO treats
166	  // every item in a quote as newly insured, so it is charged on every quote,
167	  // including a long-standing customer's follow-up contract. That makes it a
168	  // fixed rate on the base — like PROCESSING_FEE is a fixed addend — rather
169	  // than a rule belonging in POLICY_ADJUSTMENTS.
170	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
171	  // Every term is added to the base, never multiplied onto a running total. The
172	  // algebraically equivalent base * (1 + rate) yields 110.00000000000001 for
173	  // base 100, which Math.ceil turns into a premium that is 1 G too high.
174	  return Math.ceil(
175	    policyBasePremium +
176	      itemSurchargesTotal(items) +
177	      firstInsuranceSurcharge +
178	      policyAdjustments(policyBasePremium, policy) +
179	      PROCESSING_FEE,
180	  );
181	};
182	
183	const isQuote = (step: Step): boolean => step.op === "quote";
184	
185	/**
186	 * A contract is created by each quote, so the number the customer already held
187	 * when `stepIndex` is reached is just the number of quotes before it. Claims are
188	 * not contracts and so do not count.
189	 */
190	const priorContractsAt = (steps: Step[], stepIndex: number): number =>
191	  steps.slice(0, stepIndex).filter(isQuote).length;
192	
193	const insuredItems = (steps: Step[], policyIndex: number): Item[] => {
194	  const step = steps[policyIndex];
195	  if (step?.op !== "quote") throw new Error(`Step ${policyIndex} did not create a policy`);
196	  return step.items;
197	};
198	
199	/**
200	 * The insured item a damage entry refers to. Matching is by `itemType` only —
201	 * a damage entry names a type, not a specific item, so with several alike items
202	 * on one policy the first match stands in for whichever was damaged.
203	 */
204	const damagedItem = (insured: Item[], damage: Damage): Item => {
205	  const item = insured.find(({ type }) => type === damage.itemType);
206	  if (!item) throw new Error(`Policy does not cover an item of type ${damage.itemType}`);
207	  return item;
208	};
209	
210	/**
211	 * Summed over EVERY item the policy covers, not just a damaged one. A claim on
212	 * one item of a multi-item policy still draws against the whole policy's sum:
213	 * damaging only the amulet of a sword + amulet policy reports a cap of 3200
214	 * (2 × 1600), not 1200 (2 × 600).
215	 *
216	 * Reads the item's `type` and nothing else. An item's `cursed` and `enchantment`
217	 * fields move its premium but never its insured value, so this stays on the
218	 * valuation side of the pricing/valuation split described at `INSURANCE_VALUES`.
219	 */
220	const insuranceSum = (policyItems: Item[]): number =>
221	  policyItems.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
222	
223	/**
224	 * The reimbursable value of a damage before the deductible. Special clauses key
225	 * off the DAMAGED ITEM's own properties, so this takes the insured item rather
226	 * than the damage entry alone.
227	 *
228	 * The spec's dragon-material clause has no branch here on purpose: full
229	 * reimbursement is already the no-clause baseline, and where dragon material
230	 * meets enchantment >= 8 the 50 % rule wins, so a `material === "dragon"`
231	 * branch could only return what these two lines already return.
232	 */
233	const reimbursedAmount = (damage: Damage, insuredItem: Item): number =>
234	  (insuredItem.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
235	    ? damage.amount * HALF_REIMBURSEMENT_RATE
236	    : damage.amount;
237	
238	/** The deductible is charged per damaged item, not once per incident. */
239	const damagePayout = (damage: Damage, insuredItem: Item): number =>
240	  reimbursedAmount(damage, insuredItem) - DEDUCTIBLE_PER_DAMAGE;
241	
242	const incidentPayout = (damages: Damage[], insured: Item[]): number =>
243	  // Rounded down, in the MHPCO's favor. Applied to the incident total rather
244	  // than to each damage, so a single incident loses at most 1 G to rounding.
245	  Math.floor(
246	    damages.reduce((total, damage) => total + damagePayout(damage, damagedItem(insured, damage)), 0),
247	  );
248	
249	/** A policy pays out at most twice the insurance sum of the items it covers. */
250	const payoutCap = (policyItems: Item[]): number =>
251	  insuranceSum(policyItems) * CAP_MULTIPLE_OF_INSURANCE_SUM;
252	
253	/**
254	 * What the policy can still pay after `paidOut` has been paid against it.
255	 *
256	 * `paidOut` is the total ever paid on the policy, not one claim's payout: the
257	 * cap belongs to the policy and is consumed by every claim made against it. No
258	 * test yet makes a second claim on one policy, so the only caller passes a
259	 * single claim's payout — naming the concept keeps that assumption visible here
260	 * rather than buried in arithmetic at the call site.
261	 */
262	const remainingCap = (policyItems: Item[], paidOut: number): number =>
263	  payoutCap(policyItems) - paidOut;
264	
265	const claimResult = (steps: Step[], policyIndex: number, damages: Damage[]) => {
266	  // The same list serves two different scopes: the payout looks up only the
267	  // damaged items within it, while the cap is drawn from all of it.
268	  const policyItems = insuredItems(steps, policyIndex);
269	  const payout = incidentPayout(damages, policyItems);
270	  return { payout, remainingCap: remainingCap(policyItems, payout) };
271	};
272	
273	export const runScenario = (scenario: Scenario): Result[] =>
274	  scenario.steps.map((step, stepIndex) => {
275	    if (step.op === "quote") {
276	      const policy = {
277	        customer: scenario.customer,
278	        priorContracts: priorContractsAt(scenario.steps, stepIndex),
279	      };
280	      return { premium: quotePremium(step.items, policy) };
281	    }
282	    return claimResult(scenario.steps, step.policy, step.incident.damages);
283	  });
